def kieme(liste, k):
    pivot = liste[len(liste) // 2]
    petits = [x for x in liste if x < pivot]
    egaux = [x for x in liste if x == pivot]
    grands = [x for x in liste if x > pivot]
    if k <= len(petits):
        return kieme(petits, k)
    if k <= len(petits) + len(egaux):
        return pivot
    return kieme(grands, k - len(petits) - len(egaux))
